// Register-row nodes, second batch: Grasshopper Maths (Operators, Trig, Util), Sets (List) and Vector
// components added one Register row at a time. Every node has a hand-computed oracle in
// dino8-app/tests/sections/95_r2*.sh (generated by tests/flowrows2_gen.py): the closed form is written next to
// the expected value there, never derived from this code. Behaviour follows the component descriptions
// Grasshopper shows for these components; where the description leaves a corner open the choice made here
// is stated in the node's description text.
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <string>
#include <vector>

#include "flow/FlowGraph.h"

namespace dino8::flow {

namespace {

PortDef In(std::string name, Kind k, Access acc = Access::Item, Value def = Value::Null(), bool optional = false) {
  PortDef p; p.name = name; p.nick = name; p.kind = k; p.access = acc; p.def = std::move(def); p.optional = optional; return p;
}
PortDef Out(std::string name, Kind k) { PortDef p; p.name = name; p.nick = name; p.kind = k; return p; }

constexpr double kPi = 3.14159265358979323846;

// A number -> number node. `f` returns false (after setting the message) to flag the node instead of emitting.
using UnaryFn = bool (*)(double x, std::string& why, double& out);

void AddUnary(const char* name, const char* nick, const char* category, const char* sub, const char* in_name,
              const char* out_name, const char* description, Value def, UnaryFn f) {
  NodeDef d; d.name = name; d.nick = nick; d.category = category; d.subcategory = sub; d.description = description;
  d.inputs = {In(in_name, Kind::Number, Access::Item, std::move(def))};
  d.outputs = {Out(out_name, Kind::Number)};
  d.eval = [f](EvalContext& c) {
    std::string why; double out = 0;
    if (!f(c.Num(0), why, out)) { c.Fail(why); return; }
    c.Out(0, Value::Number(out));
  };
  Registry::Get().Add(d);
}

bool Equal(const Value& a, const Value& b) {
  auto numeric = [](Kind k) { return k == Kind::Number || k == Kind::Integer || k == Kind::Boolean; };
  if (numeric(a.kind) && numeric(b.kind)) return a.num == b.num;
  if (a.kind != b.kind) return false;
  switch (a.kind) {
    case Kind::Text: return a.text == b.text;
    case Kind::Point: case Kind::Vector: return a.point.x == b.point.x && a.point.y == b.point.y && a.point.z == b.point.z;
    default: return false;
  }
}

// Index into a list of `n` items. wrap: modulo n (negative counts from the end); else out of range -> -1.
long long Resolve(long long i, size_t n, bool wrap) {
  if (n == 0) return -1;
  const long long len = static_cast<long long>(n);
  if (wrap) { i %= len; if (i < 0) i += len; return i; }
  return (i >= 0 && i < len) ? i : -1;
}

void AddMaths() {
  AddUnary("Absolute", "Abs", "Maths", "Operators", "Value", "Result", "The absolute value of a number.", Value::Number(0),
           [](double x, std::string&, double& o) { o = std::fabs(x); return true; });
  AddUnary("Square Root", "Sqrt", "Maths", "Operators", "Value", "Result", "The square root of a number; negative input is flagged.", Value::Number(0),
           [](double x, std::string& why, double& o) {
             if (x < 0) { why = "Square root of a negative number"; return false; }
             o = std::sqrt(x); return true; });
  AddUnary("Cube Root", "Cbrt", "Maths", "Operators", "Value", "Result", "The real cube root of a number (negative input gives a negative root).", Value::Number(0),
           [](double x, std::string&, double& o) { o = std::cbrt(x); return true; });
  AddUnary("Logarithm", "Log", "Maths", "Operators", "Value", "Result", "Base-10 logarithm; input must be positive.", Value::Number(10),
           [](double x, std::string& why, double& o) {
             if (!(x > 0)) { why = "Logarithm needs a positive value"; return false; }
             o = std::log10(x); return true; });
  AddUnary("Natural Logarithm", "Ln", "Maths", "Operators", "Value", "Result", "Base-e logarithm; input must be positive.", Value::Number(1),
           [](double x, std::string& why, double& o) {
             if (!(x > 0)) { why = "Natural logarithm needs a positive value"; return false; }
             o = std::log(x); return true; });
  AddUnary("Exponent", "Exp", "Maths", "Operators", "Value", "Result", "e raised to a power, e^x.", Value::Number(1),
           [](double x, std::string&, double& o) { o = std::exp(x); return true; });
  {
    NodeDef d; d.name = "Log N"; d.nick = "LogN"; d.category = "Maths"; d.subcategory = "Operators";
    d.description = "Logarithm of a value in an arbitrary base; value must be positive, base positive and not 1.";
    d.inputs = {In("Value", Kind::Number, Access::Item, Value::Number(1)), In("Base", Kind::Number, Access::Item, Value::Number(10))};
    d.outputs = {Out("Result", Kind::Number)};
    d.eval = [](EvalContext& c) {
      const double x = c.Num(0), b = c.Num(1);
      if (!(x > 0)) { c.Fail("Log N needs a positive value"); return; }
      if (!(b > 0) || b == 1) { c.Fail("Log N needs a positive base other than 1"); return; }
      c.Out(0, Value::Number(std::log(x) / std::log(b)));
    };
    Registry::Get().Add(d);
  }
  {
    NodeDef d; d.name = "Integer Division"; d.nick = "A\\B"; d.category = "Maths"; d.subcategory = "Operators";
    d.description = "Integer division truncating toward zero: -7 \\ 2 = -3. A zero divisor is flagged.";
    d.inputs = {In("A", Kind::Integer, Access::Item, Value::Integer(0)), In("B", Kind::Integer, Access::Item, Value::Integer(1))};
    d.outputs = {Out("Result", Kind::Integer)};
    d.eval = [](EvalContext& c) {
      const long long a = c.Int(0), b = c.Int(1);
      if (b == 0) { c.Fail("Division by zero"); return; }
      c.Out(0, Value::Integer(a / b));
    };
    Registry::Get().Add(d);
  }
  {
    NodeDef d; d.name = "Modulus"; d.nick = "A%B"; d.category = "Maths"; d.subcategory = "Operators";
    d.description = "Remainder of integer division; takes the sign of A (so -7 mod 3 = -1), consistent with Integer Division. A zero divisor is flagged.";
    d.inputs = {In("A", Kind::Integer, Access::Item, Value::Integer(0)), In("B", Kind::Integer, Access::Item, Value::Integer(1))};
    d.outputs = {Out("Result", Kind::Integer)};
    d.eval = [](EvalContext& c) {
      const long long a = c.Int(0), b = c.Int(1);
      if (b == 0) { c.Fail("Modulus by zero"); return; }
      c.Out(0, Value::Integer(a % b));
    };
    Registry::Get().Add(d);
  }
  AddUnary("Round", "Round", "Maths", "Operators", "Value", "Result", "Rounds to the nearest whole number; exact halves round away from zero.", Value::Number(0),
           [](double x, std::string&, double& o) { o = std::round(x); return true; });
  AddUnary("Floor", "Floor", "Maths", "Operators", "Value", "Result", "The largest whole number not above the value.", Value::Number(0),
           [](double x, std::string&, double& o) { o = std::floor(x); return true; });
  AddUnary("Ceiling", "Ceil", "Maths", "Operators", "Value", "Result", "The smallest whole number not below the value.", Value::Number(0),
           [](double x, std::string&, double& o) { o = std::ceil(x); return true; });
  AddUnary("Truncate", "Trunc", "Maths", "Operators", "Value", "Result", "Drops the fractional part (rounds toward zero).", Value::Number(0),
           [](double x, std::string&, double& o) { o = std::trunc(x); return true; });

  struct Gate { const char* name; const char* nick; bool two; bool (*f)(bool, bool); const char* what; };
  static const Gate gates[] = {
      {"Gate And", "And", true, [](bool a, bool b) { return a && b; }, "True only when both A and B are true."},
      {"Gate Or", "Or", true, [](bool a, bool b) { return a || b; }, "True when A or B (or both) is true."},
      {"Gate Xor", "Xor", true, [](bool a, bool b) { return a != b; }, "True when exactly one of A and B is true."},
      {"Gate Nand", "Nand", true, [](bool a, bool b) { return !(a && b); }, "Not (A and B)."},
      {"Gate Nor", "Nor", true, [](bool a, bool b) { return !(a || b); }, "Not (A or B)."},
      {"Gate Xnor", "Xnor", true, [](bool a, bool b) { return a == b; }, "True when A and B are equal."},
      {"Gate Not", "Not", false, [](bool a, bool) { return !a; }, "The opposite of A."},
  };
  for (const Gate& g : gates) {
    NodeDef d; d.name = g.name; d.nick = g.nick; d.category = "Maths"; d.subcategory = "Operators"; d.description = g.what;
    d.inputs = {In("A", Kind::Boolean, Access::Item, Value::Boolean(false))};
    if (g.two) d.inputs.push_back(In("B", Kind::Boolean, Access::Item, Value::Boolean(false)));
    d.outputs = {Out("Result", Kind::Boolean)};
    auto f = g.f; const bool two = g.two;
    d.eval = [f, two](EvalContext& c) { c.Out(0, Value::Boolean(f(c.Bool(0), two ? c.Bool(1) : false))); };
    Registry::Get().Add(d);
  }
}

void AddTrig() {
  AddUnary("Sine", "Sin", "Maths", "Trig", "Angle", "Result", "Sine of an angle given in radians.", Value::Number(0),
           [](double x, std::string&, double& o) { o = std::sin(x); return true; });
  AddUnary("Cosine", "Cos", "Maths", "Trig", "Angle", "Result", "Cosine of an angle given in radians.", Value::Number(0),
           [](double x, std::string&, double& o) { o = std::cos(x); return true; });
  AddUnary("Tangent", "Tan", "Maths", "Trig", "Angle", "Result", "Tangent of an angle given in radians.", Value::Number(0),
           [](double x, std::string&, double& o) { o = std::tan(x); return true; });
  AddUnary("Arcsin", "Asin", "Maths", "Trig", "Value", "Angle", "Inverse sine, an angle in radians in [-pi/2, pi/2]; input must lie in [-1, 1].", Value::Number(0),
           [](double x, std::string& why, double& o) {
             if (x < -1 || x > 1) { why = "Arcsin needs a value between -1 and 1"; return false; }
             o = std::asin(x); return true; });
  AddUnary("Arccos", "Acos", "Maths", "Trig", "Value", "Angle", "Inverse cosine, an angle in radians in [0, pi]; input must lie in [-1, 1].", Value::Number(0),
           [](double x, std::string& why, double& o) {
             if (x < -1 || x > 1) { why = "Arccos needs a value between -1 and 1"; return false; }
             o = std::acos(x); return true; });
  AddUnary("Arctan", "Atan", "Maths", "Trig", "Value", "Angle", "Inverse tangent, an angle in radians in (-pi/2, pi/2).", Value::Number(0),
           [](double x, std::string&, double& o) { o = std::atan(x); return true; });
  AddUnary("Degrees", "Deg", "Maths", "Trig", "Radians", "Degrees", "Converts an angle in radians to degrees.", Value::Number(0),
           [](double x, std::string&, double& o) { o = x * (180.0 / kPi); return true; });
  AddUnary("Radians", "Rad", "Maths", "Trig", "Degrees", "Radians", "Converts an angle in degrees to radians.", Value::Number(0),
           [](double x, std::string&, double& o) { o = x * (kPi / 180.0); return true; });
  AddUnary("Pi", "Pi", "Maths", "Trig", "Factor", "Result", "A multiple of pi: Result = Factor * pi (Factor 1 gives pi itself).", Value::Number(1),
           [](double x, std::string&, double& o) { o = x * kPi; return true; });
  AddUnary("Golden Ratio", "Phi", "Maths", "Trig", "Factor", "Result", "A multiple of the golden ratio: Result = Factor * (1 + sqrt 5) / 2.", Value::Number(1),
           [](double x, std::string&, double& o) { o = x * ((1.0 + std::sqrt(5.0)) / 2.0); return true; });
  {
    NodeDef d; d.name = "Maximum"; d.nick = "Max"; d.category = "Maths"; d.subcategory = "Util";
    d.description = "The larger of A and B. A value that is not a number (NaN) never wins against a number.";
    d.inputs = {In("A", Kind::Number, Access::Item, Value::Number(0)), In("B", Kind::Number, Access::Item, Value::Number(0))};
    d.outputs = {Out("Result", Kind::Number)};
    d.eval = [](EvalContext& c) { c.Out(0, Value::Number(std::fmax(c.Num(0), c.Num(1)))); };
    Registry::Get().Add(d);
  }
  {
    NodeDef d; d.name = "Minimum"; d.nick = "Min"; d.category = "Maths"; d.subcategory = "Util";
    d.description = "The smaller of A and B. A value that is not a number (NaN) never wins against a number.";
    d.inputs = {In("A", Kind::Number, Access::Item, Value::Number(0)), In("B", Kind::Number, Access::Item, Value::Number(0))};
    d.outputs = {Out("Result", Kind::Number)};
    d.eval = [](EvalContext& c) { c.Out(0, Value::Number(std::fmin(c.Num(0), c.Num(1)))); };
    Registry::Get().Add(d);
  }
}

// The k-th of `items` matched to the k-th of a longer list: the last item repeats (Grasshopper data matching).
const Value& Matched(const std::vector<Value>& items, size_t k) { return items[std::min(k, items.size() - 1)]; }

void AddSets() {
  Registry& r = Registry::Get();
  {
    NodeDef d; d.name = "Cull Index"; d.nick = "CullI"; d.category = "Sets"; d.subcategory = "List";
    d.description = "Removes the items at the given indices. Wrap off: indices outside the list are ignored; wrap on: they wrap around (-1 is the last item).";
    d.inputs = {In("List", Kind::Any, Access::List), In("Indices", Kind::Integer, Access::List), In("Wrap", Kind::Boolean, Access::Item, Value::Boolean(false))};
    d.outputs = {Out("List", Kind::Any)};
    d.eval = [](EvalContext& c) {
      const std::vector<Value>& l = c.List(0);
      const bool wrap = c.Bool(2, false);
      std::vector<bool> drop(l.size(), false);
      for (const Value& iv : c.List(1)) {
        double x; if (!iv.AsNumber(x) || !std::isfinite(x)) continue;
        const long long i = Resolve(static_cast<long long>(std::clamp(x, -2.0e9, 2.0e9)), l.size(), wrap);
        if (i >= 0) drop[static_cast<size_t>(i)] = true;
      }
      std::vector<Value> out;
      for (size_t i = 0; i < l.size(); ++i) if (!drop[i]) out.push_back(l[i]);
      c.OutList(0, out);
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Dispatch"; d.nick = "Dispatch"; d.category = "Sets"; d.subcategory = "List";
    d.description = "Splits a list by a repeating boolean pattern: items whose pattern entry is true go to List A, the rest to List B. An empty pattern sends everything to List A.";
    d.inputs = {In("List", Kind::Any, Access::List), In("Pattern", Kind::Boolean, Access::List)};
    d.outputs = {Out("List A", Kind::Any), Out("List B", Kind::Any)};
    d.eval = [](EvalContext& c) {
      const std::vector<Value>& l = c.List(0);
      const std::vector<Value>& pat = c.List(1);
      std::vector<Value> a, b;
      for (size_t i = 0; i < l.size(); ++i) {
        bool to_a = true;
        if (!pat.empty()) pat[i % pat.size()].AsBool(to_a);
        (to_a ? a : b).push_back(l[i]);
      }
      c.OutList(0, a);
      c.OutList(1, b);
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Replace Items"; d.nick = "Replace"; d.category = "Sets"; d.subcategory = "List";
    d.description = "Replaces the items at the given indices with the given items (the k-th index takes the k-th item; a shorter item list repeats its last item). Wrap off: indices outside the list are ignored.";
    d.inputs = {In("List", Kind::Any, Access::List), In("Item", Kind::Any, Access::List), In("Indices", Kind::Integer, Access::List),
                In("Wrap", Kind::Boolean, Access::Item, Value::Boolean(false))};
    d.outputs = {Out("List", Kind::Any)};
    d.eval = [](EvalContext& c) {
      std::vector<Value> l = c.List(0);
      const std::vector<Value>& items = c.List(1);
      const bool wrap = c.Bool(3, false);
      size_t k = 0;
      for (const Value& iv : c.List(2)) {
        double x; if (!iv.AsNumber(x) || !std::isfinite(x)) { ++k; continue; }
        const long long i = Resolve(static_cast<long long>(std::clamp(x, -2.0e9, 2.0e9)), l.size(), wrap);
        if (i >= 0 && !items.empty()) l[static_cast<size_t>(i)] = Matched(items, k);
        ++k;
      }
      c.OutList(0, l);
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Insert Items"; d.nick = "Insert"; d.category = "Sets"; d.subcategory = "List";
    d.description = "Inserts items into a list: the k-th item goes directly in front of the original item at the k-th index (index = list length appends). Items sharing an index keep their order. Wrap off: indices are clamped into [0, length]; wrap on: they wrap modulo length+1.";
    d.inputs = {In("List", Kind::Any, Access::List), In("Item", Kind::Any, Access::List), In("Indices", Kind::Integer, Access::List),
                In("Wrap", Kind::Boolean, Access::Item, Value::Boolean(false))};
    d.outputs = {Out("List", Kind::Any)};
    d.eval = [](EvalContext& c) {
      const std::vector<Value>& l = c.List(0);
      const std::vector<Value>& items = c.List(1);
      const bool wrap = c.Bool(3, false);
      const long long n = static_cast<long long>(l.size());
      std::vector<std::vector<Value>> at(l.size() + 1);
      size_t k = 0;
      for (const Value& iv : c.List(2)) {
        double x; if (!iv.AsNumber(x) || !std::isfinite(x)) { ++k; continue; }
        long long i = static_cast<long long>(std::clamp(x, -2.0e9, 2.0e9));
        if (wrap) { i %= (n + 1); if (i < 0) i += n + 1; } else { i = std::clamp<long long>(i, 0, n); }
        if (!items.empty()) at[static_cast<size_t>(i)].push_back(Matched(items, k));
        ++k;
      }
      std::vector<Value> out;
      for (size_t p = 0; p <= l.size(); ++p) {
        for (const Value& v : at[p]) out.push_back(v);
        if (p < l.size()) out.push_back(l[p]);
      }
      c.OutList(0, out);
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Item Index"; d.nick = "Index"; d.category = "Sets"; d.subcategory = "List";
    d.description = "The index of the first item of the list equal to the searched item (numbers compare by value, text by content, points by coordinates); -1 when it is not found.";
    d.inputs = {In("List", Kind::Any, Access::List), In("Item", Kind::Any, Access::Item)};
    d.outputs = {Out("Index", Kind::Integer)};
    d.eval = [](EvalContext& c) {
      const std::vector<Value>& l = c.List(0);
      long long found = -1;
      for (size_t i = 0; i < l.size(); ++i) if (Equal(l[i], c.In(1))) { found = static_cast<long long>(i); break; }
      if (found < 0) c.Warn("Item not found in the list");
      c.Out(0, Value::Integer(found));
    };
    r.Add(d);
  }
}

void AddVectors() {
  Registry& r = Registry::Get();
  {
    NodeDef d; d.name = "Vector 2Pt"; d.nick = "Vec2Pt"; d.category = "Vector"; d.subcategory = "Vector";
    d.description = "The vector from point A to point B, optionally unitized; Length is the length of the vector before unitizing. A zero vector stays zero when unitizing.";
    d.inputs = {In("Base", Kind::Point, Access::Item, Value::Point(Point3d(0, 0, 0))), In("Tip", Kind::Point, Access::Item, Value::Point(Point3d(0, 0, 1))),
                In("Unitize", Kind::Boolean, Access::Item, Value::Boolean(false))};
    d.outputs = {Out("Vector", Kind::Vector), Out("Length", Kind::Number)};
    d.eval = [](EvalContext& c) {
      Vector3d v = c.Pt(1) - c.Pt(0);
      const double len = v.Length();
      if (c.Bool(2, false) && len > 1e-12) v.Unitize();
      c.Out(0, Value::Vector(v));
      c.Out(1, Value::Number(len));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Amplitude"; d.nick = "Amp"; d.category = "Vector"; d.subcategory = "Vector";
    d.description = "Gives a vector a new length, keeping its direction. A zero vector has no direction and is flagged.";
    d.inputs = {In("Vector", Kind::Vector, Access::Item, Value::Vector(Vector3d(0, 0, 1))), In("Amplitude", Kind::Number, Access::Item, Value::Number(1))};
    d.outputs = {Out("Vector", Kind::Vector)};
    d.eval = [](EvalContext& c) {
      Vector3d v = c.Vec(0);
      const double len = v.Length();
      if (!(len > 1e-12)) { c.Fail("A zero-length vector has no direction"); return; }
      c.Out(0, Value::Vector(v * (c.Num(1) / len)));
    };
    r.Add(d);
  }
}

}  // namespace

void RegisterRowNodes2() {
  AddMaths();
  AddTrig();
  AddSets();
  AddVectors();
}

}  // namespace dino8::flow
